using System.Globalization;
using System.Reflection;

namespace Aeralis.Illustrations;

/// <summary>
/// The overall size of each aircraft, in millimetres.
/// </summary>
/// <remarks>
/// Generated by <c>tools/gen_aircraft_views.py</c> into <c>Resources/dimensions.csv</c> and
/// embedded here, from the same fleet table the drawings themselves are drawn from — the side
/// view length by height, the plan span by length, the front span by height. What a dimension
/// line reports is therefore what the drawing beneath it actually measures, and the two cannot
/// drift apart.
/// <para>
/// A type is absent when the table cannot give all three, in which case <c>ShowDimensions</c>
/// draws nothing for it: every view carries two dimension lines and one of them would come out
/// blank.
/// </para>
/// </remarks>
internal sealed record Dimensions(double Length, double Span, double Height)
{
    private static readonly Lazy<Dictionary<string, Dimensions>> All = new(Load);

    public static Dimensions? For(AircraftType aircraft, string resourceKey) =>
        All.Value.GetValueOrDefault(resourceKey);

    /// <summary>The two dimensions a view shows, across and up the page, with their labels.</summary>
    public (double Across, string AcrossLabel, double Up, string UpLabel) ForView(ViewKind view) => view switch
    {
        ViewKind.Plan => (Span, "SPAN", Length, "LENGTH"),
        ViewKind.Side => (Length, "LENGTH", Height, "HEIGHT"),
        ViewKind.Front => (Span, "SPAN", Height, "HEIGHT"),
        _ => throw new ArgumentOutOfRangeException(nameof(view)),
    };

    /// <summary>Formats a millimetre measurement the way the manuals do: feet over metres.</summary>
    public static (string Feet, string Metres) Format(double millimetres)
    {
        var metres = millimetres / 1000.0;
        return ($"{metres / 0.3048:F2}Ft", $"{metres:F2}m");
    }

    private static Dictionary<string, Dimensions> Load()
    {
        const string resource = "Aeralis.Illustrations.Resources.dimensions.csv";

        using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(resource)
            ?? throw new InvalidOperationException($"embedded '{resource}' is missing");
        using var reader = new StreamReader(stream);

        var result = new Dictionary<string, Dimensions>(StringComparer.OrdinalIgnoreCase);
        reader.ReadLine();

        while (reader.ReadLine() is { } line)
        {
            var fields = line.Split(',');
            if (fields.Length < 4) continue;

            // A column is empty when the published sheet cannot say — the CIRRANEs are drawn as a
            // plan view alone, which gives length and span but nothing about height. A partial
            // row is dropped rather than half-used: every view draws two dimension lines, so an
            // aircraft with only some of its dimensions would still draw a blank one. Leaving
            // the type out instead makes ShowDimensions a no-op for it.
            if (!TryParse(fields[1], out var length) || !TryParse(fields[2], out var span) || !TryParse(fields[3], out var height))
                continue;

            result[fields[0]] = new Dimensions(length, span, height);
        }

        return result;
    }

    private static bool TryParse(string field, out double value) =>
        double.TryParse(field, NumberStyles.Float, CultureInfo.InvariantCulture, out value);
}
